def is_app_store_delisting_or_restoration_story(title: str, text: str) -> bool:
    """Identify a named app's material removal from or restoration to Apple's store."""
    lead = title_and_lead_scope(title, text, limit=1000).lower()
    title_lower = title.lower()
    if score_terms(lead, ["app store", "苹果应用商店", "苹果 app store"]) <= 0:
        return False
    title_store_action = score_terms(
        title_lower,
        [
            "pulled from",
            "removed from",
            "delisted",
            "disappeared from",
            "restored",
            "returned to",
            "relisted",
            "下架",
            "移除",
            "恢复上架",
            "重新上架",
        ],
    ) > 0 or bool(
        re.search(
            r"\b(?:remove|pull|delist)\b.{0,80}\bfrom\s+(?:the\s+)?(?:apple(?:'s)?\s+)?app store\b",
            title_lower,
        )
    )
    current_lead = lead[:650]
    current_lead_store_action = bool(
        score_terms(
            current_lead,
            [
                "vanished from",
                "disappeared from",
                "pulled from",
                "removed from",
                "delisted from",
                "restored to",
                "returned to",
                "relisted on",
                "下架",
                "移除",
                "恢复上架",
                "重新上架",
            ],
        )
        > 0
        and score_terms(
            current_lead,
            [
                "today",
                "this week",
                "this month",
                "roughly an hour",
                "for an hour",
                "briefly",
                "temporarily",
                "今日",
                "本周",
                "本月",
                "短暂",
                "临时",
                "一小时",
            ],
        )
        > 0
    )
    if not title_store_action and not current_lead_store_action:
        return False
    if score_terms(
        title_lower,
        [
            "acquires",
            "acquired",
            "acquisition",
            "buys",
            "bought",
            "收购",
            "并购",
        ],
    ) > 0:
        return False
    if re.search(
        r"\b(?:indie app spotlight|app spotlight|app pick)\b|(?:应用|app)推荐",
        title_lower,
    ):
        return False
    # Ordinary app releases and feature updates remain third-party noise.
    return not bool(
        score_terms(title.lower(), ["launches on", "new app", "app update", "功能更新", "新版上线"])
        and score_terms(title.lower(), ["pulled", "removed", "delisted", "restored", "下架", "恢复上架"]) == 0
    )


def is_current_versioned_first_party_feature_story(title: str, text: str) -> bool:
    """Keep a concrete current OS feature even when the headline uses editorial framing."""
    identity = title_led_identity(title, title_and_lead_scope(title, text, limit=900))
    os_products = identity.title_products & {
        "ios",
        "ipados",
        "macos",
        "watchos",
        "tvos",
        "visionos",
    }
    first_party_products = identity.title_products - {
        "iphone",
        "ipad",
        "mac",
        "macbook",
        *os_products,
    }
    if (
        identity.scope != "apple-direct"
        or len(os_products) != 1
        or not first_party_products
        or identity.content_form in {"buying_advice", "deal", "roundup", "tutorial"}
    ):
        return False
    title_lower = title.lower()
    if not re.search(r"\b(?:ios|ipados|macos|watchos|tvos|visionos)\s+\d+(?:\.\d+)?\b", title_lower):
        return False
    lead = title_and_lead_scope(title, text, limit=1000).lower()
    return bool(
        (
            "feature-change" in identity.title_actions
            or score_terms(
                lead,
                ["losing", "removed", "disappear", "drops", "移除", "下线", "消失"],
            )
            > 0
        )
        and score_terms(
            lead,
            [
                "adds",
                "added",
                "gains",
                "new feature",
                "new capability",
                "will be able to",
                "lets users",
                "losing",
                "removed",
                "disappear",
                "drops",
                "新增",
                "加入",
                "支持",
                "新功能",
                "可让用户",
                "移除",
                "下线",
                "消失",
            ],
        )
        > 0
    )


def is_current_versioned_apple_device_compatibility_story(title: str, text: str) -> bool:
    """Recognize factual OS/device support matrices rather than reader-choice polls."""
    title_lower = clean_sentence(title).lower()
    lead = title_and_lead_scope(title, text, limit=1200).lower()
    identity = title_led_identity(title, lead)
    if identity.scope != "apple-direct":
        return False
    if not re.search(
        r"\b(?:ios|ipados|macos|watchos|tvos|visionos)\s+\d+(?:\.\d+){0,2}\b",
        title_lower,
    ):
        return False
    if not re.search(
        r"^(?:which|what)\s+(?:iphones?|ipads?|macs?|apple watches?|devices?)\s+"
        r"(?:support|get|can use)\b|"
        r"\b(?:supported|compatible)\s+(?:iphones?|ipads?|macs?|apple watches?|devices?)\b|"
        r"^(?:哪些|什么)\s*(?:iphone|ipad|mac|apple watch|设备).{0,24}(?:支持|兼容|可用)",
        title_lower,
    ):
        return False
    compatibility_evidence = bool(
        re.search(
            r"\b(?:compatible with|supports?|support tiers?|requirements?|requires?|"
            r"and later|or later|only\s+\w+\s+(?:iphones?|ipads?|macs?|devices?))\b|"
            r"(?:兼容|支持机型|支持列表|分为.{0,10}档|仅.{0,12}(?:款|台).{0,8}支持|及后续机型|最低要求)",
            lead,
        )
    )
    concrete_boundary = bool(
        re.search(
            r"\b(?:iphone|ipad|mac|apple watch)\s+\d+\b|"
            r"\b\d+\s*gb\b|\b(?:two|three|four|five|\d+)\s+(?:tiers?|models?|devices?)\b|"
            r"(?:iphone|ipad|mac|apple watch)\s*\d+|\d+\s*gb|(?:两|三|四|五|六|\d+)\s*(?:档|款|台)",
            lead,
        )
    )
    return compatibility_evidence and concrete_boundary


