def is_non_actionable_recap_title(title: str) -> bool:
    title_lower = title.lower().strip()
    return bool(re.match(r"^top stories\b", title_lower))


def is_rumor_feature_recap_without_new_reporting(title: str, text: str) -> bool:
    """Detect list-style rumor recaps that do not report a new Apple event."""
    title_lower = title.lower()
    lower = f"{title} {text}".lower()
    english_list_title = bool(
        re.search(
            r"\b(?:with|these|up to)\s+(?:at least\s+)?"
            r"(?:\d+|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve)\s+"
            r"(?:new\s+)?features?\b",
            title_lower,
        )
        or re.search(
            r"\b(?:\d+|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve)\s+"
            r"(?:rumored\s+)?(?:new\s+)?features?\b",
            title_lower,
        )
        or re.search(
            r"\b(?:latest (?:apple )?rumors?|all (?:the )?(?:apple )?rumors?|rumors? so far)\b",
            title_lower,
        )
        or re.search(r"\brumors\s*:", title_lower)
        or "rumor reality check" in title_lower
    )
    chinese_roundup_title = score_terms(
        title_lower,
        ["有何看点", "新品盘点", "功能盘点", "传闻汇总", "爆料汇总", "新品汇总", "一文看懂"],
    ) > 0 or bool(re.search(r"\d+\s*项(?:升级|变化|新功能)(?:[^。！？\n]{0,16})(?:解析|盘点|汇总|总结)", title_lower))
    if not (english_list_title or chinese_roundup_title):
        return False
    recap_evidence = score_terms(
        lower,
        [
            "below, we have recapped",
            "we have recapped",
            "recapped rumors",
            "rumored new features",
            "rumored features",
            "multiple reports",
            "previously reported",
            "previous rumor",
            "previous rumors",
            "rumors say",
            "rumors suggest",
            "rumor mill",
            "rumored so far",
            "features to expect",
            "here's what you need to know",
            "heres what you need to know",
            "if a previous rumor is still accurate",
            "no guarantee that this rumor is accurate",
            "as of july",
            "no new reporting",
            "without new reporting",
            "looked back at everything we know so far",
            "ranked the most consistent rumors",
            "据多家媒体披露",
            "汇总爆料",
            "汇总此前传闻",
            "盘点此前传闻",
            "目前已经曝光",
            "进行总结解析",
            "此前已有报道",
            "没有新增消息",
            "无新增消息",
        ],
    )
    return recap_evidence > 0


def is_editorial_multi_generation_roadmap_recap(title: str, text: str) -> bool:
    """Detect rhetorical roadmap recaps spanning product generations without a new report."""
    title_lower = clean_sentence(title).lower()
    generations = {
        match.group(1)
        for match in re.finditer(
            r"\biphone\s*(\d{1,2})(?=$|[^a-z0-9])",
            title_lower,
        )
    }
    implied_leading_generation = re.match(
        r"^\s*(\d{2})\s*(?:还没|尚未|仍未|未).{0,12}(?:发布|上市|亮相)",
        title_lower,
    )
    if implied_leading_generation:
        generations.add(implied_leading_generation.group(1))
    if len(generations) < 2:
        return False
    editorial_framing = bool(
        re.search(
            r"\b(?:already know|know already|everything (?:we|you) know|no secrets?|"
            r"before .{0,24}(?:launch|release))\b|"
            r"(?:提前知道|都知道|已经知道|全知道|一切已知|还没.{0,16}就|尚未.{0,16}就|无秘密|没有秘密)",
            title_lower,
        )
    )
    if not editorial_framing:
        return False
    lead = title_and_lead_scope(title, text, limit=900).lower()
    current_report = score_terms(
        lead,
        [
            "new report",
            "reported today",
            "according to bloomberg",
            "according to analyst",
            "research note",
            "supply-chain report",
            "最新报道",
            "今日报告",
            "分析师称",
            "研报称",
            "供应链报告",
        ],
    ) > 0
    return not current_report


def is_unsourced_multi_product_outlook_without_new_reporting(title: str, text: str) -> bool:
    """Detect publisher-built Apple product calendars that only aggregate prior rumors."""
    title_lower = title.lower()
    title_signal = bool(
        re.search(
            r"\bapple\b.{0,28}\b(?:plans?\s+to|expected\s+to|will|to)\s+"
            r"(?:release|launch|unveil)\b.{0,20}\b"
            r"(?:\d+|one|two|three|four|five|six|seven|eight|nine|ten|these\s+\d+)\s+"
            r"(?:new\s+)?(?:products?|devices?)\b",
            title_lower,
        )
        or re.search(
            r"(?:苹果).{0,20}(?:计划|预计|将).{0,10}(?:发布|推出|亮相).{0,12}"
            r"\d+\s*款(?:新品|产品|设备)",
            title_lower,
        )
    )
    if not title_signal:
        return False

    families = hardware_product_families_from_text(f"{title} {text[:1800]}")
    if "mac" in families and families & {"macbook", "imac", "mac-mini", "mac-studio"}:
        families.discard("mac")
    announced_count_match = re.search(
        r"\b(?:release|launch|unveil)\s+"
        r"(\d+|one|two|three|four|five|six|seven|eight|nine|ten)\s+"
        r"(?:new\s+)?(?:products?|devices?)\b",
        title_lower,
    )
    count_words = {
        "one": 1,
        "two": 2,
        "three": 3,
        "four": 4,
        "five": 5,
        "six": 6,
        "seven": 7,
        "eight": 8,
        "nine": 9,
        "ten": 10,
    }
    announced_count_token = announced_count_match.group(1) if announced_count_match else ""
    announced_count = (
        int(announced_count_token)
        if announced_count_token.isdigit()
        else count_words.get(announced_count_token, 0)
    )
    if len(families) < 3 and not (announced_count >= 3 and len(families) >= 2):
        return False

    lead = title_and_lead_scope(title, text, limit=850).lower()
    current_attribution = score_terms(
        lead,
        [
            "according to bloomberg",
            "according to mark gurman",
            "bloomberg reports",
            "gurman reports",
            "reported today",
            "new report",
            "research note",
            "supply-chain report",
            "according to analyst",
            "据彭博社",
            "古尔曼称",
            "最新报道",
            "今日报告",
            "研报称",
            "供应链报告",
            "分析师称",
        ],
    ) > 0 and score_terms(
        lead,
        [
            "no new report",
            "without a new report",
            "without new reporting",
            "previously published rumors",
            "无新增报道",
            "没有新增报道",
            "汇总此前传闻",
        ],
    ) == 0
    return not current_attribution


def is_non_apple_industry_forecast_with_apple_price_hook(title: str, text: str) -> bool:
    """Detect a non-Apple industry forecast fronted by an unattributed Apple price hook."""
    title_lower = title.lower()
    clauses = [part.strip() for part in re.split(r"[!！|｜;；]", title_lower) if part.strip()]
    if len(clauses) < 2:
        return False
    apple_hook, tail = clauses[0], " ".join(clauses[1:])
    if score_terms(apple_hook, ["apple", "iphone", "ipad", "mac", "苹果"]) <= 0:
        return False
    if score_terms(
        apple_hook,
        [
            "price increase",
            "price hike",
            "more expensive",
            "starting price",
            "涨价",
            "提价",
            "价格",
            "售价",
        ],
    ) <= 0:
        return False

    actor_match = re.match(r"\s*([^:：]{1,32})[:：]\s*(.+)", tail)
    if not actor_match:
        return False
    actor, action = actor_match.groups()
    if score_terms(actor, ["apple", "iphone", "ipad", "mac", "苹果"]) > 0:
        return False
    industry_subject = score_terms(
        action,
        [
            "industry",
            "market",
            "memory",
            "storage",
            "dram",
            "nand",
            "semiconductor",
            "capacity",
            "supply",
            "shortage",
            "行业",
            "市场",
            "内存",
            "存储",
            "半导体",
            "产能",
            "供应",
            "短缺",
        ],
    ) > 0
    forecast_action = score_terms(
        action,
        [
            "says",
            "warns",
            "expects",
            "predicts",
            "forecasts",
            "will last",
            "will worsen",
            "称",
            "表示",
            "警告",
            "预计",
            "预测",
            "持续",
            "加剧",
        ],
    ) > 0
    if not (industry_subject and forecast_action):
        return False

    direct_or_attributed_apple_action = score_terms(
        apple_hook,
        [
            "apple announces",
            "apple confirms",
            "apple raises",
            "apple raised",
            "apple says",
            "according to",
            "analyst",
            "research note",
            "report by",
            "苹果宣布",
            "苹果确认",
            "苹果上调",
            "苹果回应",
            "分析师",
            "研报",
            "报告称",
            "机构",
        ],
    ) > 0
    return not direct_or_attributed_apple_action


