def is_apple_strategic_transaction_story(text: str) -> bool:
    lower = text.lower()
    if effective_apple_term_score(lower) <= 0:
        return False
    transaction_score = score_terms(
        lower,
        [
            "merger",
            "merge",
            "merging",
            "acquisition",
            "acquire",
            "acquires",
            "acquired",
            "acquiring",
            "buyout",
            "takeover",
            "purchases",
            "purchasing",
            "strategic deal",
            "transaction",
            "合并",
            "并购",
            "收购",
            "交易",
        ],
    )
    if transaction_score <= 0:
        return False
    direct_acquisition = (
        re.search(r"\bapple\b[^.!?。！？]{0,64}\b(?:acquires?|acquired|acquiring|buys?|bought|purchased|purchasing)\b", lower)
        is not None
        or re.search(r"\b(?:acquired|acquiring|bought|purchased|purchasing)\b[^.!?。！？]{0,48}\bby\s+apple\b", lower)
        is not None
        or re.search(r"苹果[^。！？.!?]{0,48}(?:收购|买下|购入)", lower) is not None
        or re.search(r"(?:被|由)苹果[^。！？.!?]{0,24}(?:收购|买下|购入)", lower) is not None
    )
    if direct_acquisition:
        return True
    discussion_score = score_terms(
        lower,
        [
            "conversation",
            "conversations",
            "talk",
            "talks",
            "talked",
            "discuss",
            "discussed",
            "discussion",
            "interest",
            "interested",
            "profile",
            "interview",
            "said",
            "says",
            "revealed",
            "沟通",
            "讨论",
            "谈判",
            "兴趣",
            "采访",
            "表示",
            "透露",
            "推进",
        ],
    )
    counterparty_score = score_terms(
        lower,
        [
            "company",
            "companies",
            "ceo",
            "executive",
            "disney",
            "twitter",
            "x corp",
            "公司",
            "企业",
            "首席执行官",
            "高管",
            "迪士尼",
            "推特",
        ],
    )
    direct_pairing = (
        re.search(r"\bapple\b[^.!?。！？]{0,48}\b(?:and|with)\b[^.!?。！？]{0,48}", lower)
        is not None
        or re.search(r"[^。！？.!?]{0,32}(?:与|和|同)苹果[^。！？.!?]{0,48}(?:合并|并购|收购|交易|沟通|讨论)", lower)
        is not None
        or re.search(r"苹果[^。！？.!?]{0,48}(?:与|和|同)[^。！？.!?]{0,48}(?:合并|并购|收购|交易|沟通|讨论)", lower)
        is not None
    )
    return discussion_score > 0 and (counterparty_score > 0 or direct_pairing)


def strategic_transaction_counterparty_facets(text: str) -> set[str]:
    raw = text[:900]
    lower = text.lower()
    facets: set[str] = set()
    counterparties = {
        "disney": ["disney", "迪士尼"],
        "twitter": ["twitter", "x corp", "推特"],
        "ai-startup": ["ai startup", "ai company", "人工智能初创", "ai 初创"],
        "rabbit-play": ["rabbit 3 times", "rabbit 3 ties", "play", "swift development tool", "app design tool"],
    }
    for name, terms in counterparties.items():
        if score_terms(lower, terms) > 0:
            facets.add(f"transaction-counterparty-{name}")
    generic_names: set[str] = set()
    patterns = [
        r"\b([A-Za-z][A-Za-z0-9.-]{2,})\s+(?:was\s+|were\s+)?acquired\s+by\s+Apple\b",
        r"苹果(?:公司)?[^。！？.!?]{0,24}(?:收购|买下|购入)[^A-Za-z0-9]{0,8}([A-Za-z][A-Za-z0-9.-]{2,})",
    ]
    for pattern in patterns:
        generic_names.update(match.group(1) for match in re.finditer(pattern, raw, re.I))
    for match in re.finditer(
        r"\bApple\b[^。！？.!?]{0,24}\b(?:acquires?|acquired|acquiring|buys?|bought|purchased)\b([^。！？.!?]{0,90})",
        raw,
        re.I,
    ):
        tail = re.split(r"\s+-\s+|\s+\|\s+", match.group(1), maxsplit=1)[0]
        words = re.findall(r"[A-Za-z][A-Za-z0-9.-]{2,}", tail)
        excluded = {
            "asset",
            "assets",
            "app",
            "apple",
            "award",
            "acquire",
            "acquired",
            "certain",
            "company",
            "employees",
            "employee",
            "hired",
            "observability",
            "part",
            "startup",
            "team",
            "that",
            "the",
            "tool",
            "won",
        }
        eligible = [word for word in words if word.lower() not in excluded]
        if eligible:
            generic_names.add(eligible[0])
    generic_names.update(
        token
        for token in re.findall(r"\b[A-Z][A-Za-z0-9.-]*[A-Z][A-Za-z0-9.-]*\b", raw)
        if token.lower() not in {"apple", "aapl"}
    )
    for value in generic_names:
        slug = re.sub(r"[^a-z0-9]+", "-", value.lower()).strip("-")
        if len(slug) >= 3 and slug not in {"apple", "inc"}:
            facets.add(f"transaction-counterparty-{slug}")
    return facets


