def is_non_apple_led_corporate_ranking_story(title: str, text: str) -> bool:
    title_lower = title.lower()
    ranking_score = score_terms(
        title_lower,
        [
            "ranking",
            "rankings",
            "ranked",
            "fortune 500",
            "top 500",
            "market cap",
            "market capitalization",
            "top companies",
            "排行榜",
            "排名",
            "市值",
            "百强",
            "500 强",
            "500强",
        ],
    )
    if ranking_score <= 0:
        return False
    if effective_apple_term_score(title) <= 0:
        if effective_apple_term_score(text) <= 0:
            return False
        if is_material_apple_stock_move_story(title, text):
            return False
        return not is_apple_specific_market_share_report_story(text, title)
    apple_is_comparison_object = bool(
        re.search(
            r"\b(?:surpasses?|overtakes?|beats?|tops?|edges?\s+out|ahead\s+of)\s+apple\b",
            title_lower,
        )
        or re.search(r"(?:超越|反超|击败|超过)苹果", title_lower)
    )
    if not apple_is_comparison_object:
        return False
    if is_material_apple_stock_move_story(title, text):
        return False
    return not is_apple_specific_market_share_report_story(text, title)


def is_non_apple_primary_legal_story_with_incidental_apple_context(
    title: str,
    lead_text: str,
    full_context: str = "",
) -> bool:
    title_lower = title.lower()
    if score_terms(
        title_lower,
        [
            "lawsuit",
            "sues",
            "suing",
            "court",
            "judge",
            "appeal",
            "legal fees",
            "antitrust",
            "诉讼",
            "起诉",
            "官司",
            "法院",
            "法官",
            "上诉",
            "法律费",
            "反垄断",
        ],
    ) <= 0:
        return False

    clean_lead = clean_sentence(lead_text)
    lead_sentences = [
        part.strip()
        for part in re.split(r"(?<=[。！？.!?])", clean_lead)
        if part.strip()
    ]
    primary_scope = f"{title} {' '.join(lead_sentences[:3])[:700]}"
    if effective_apple_term_score(primary_scope) > 0 or loose_apple_product_marker(primary_scope):
        return False

    complete_scope = f"{title} {lead_text} {full_context}"
    return effective_apple_term_score(complete_scope) > 0 or loose_apple_product_marker(complete_scope)


def is_broad_non_apple_service_market_report_story(title: str, text: str) -> bool:
    title_lower = title.lower()
    lower = text.lower()
    apple_services = ["apple music", "apple tv+", "apple tv plus", "apple arcade", "icloud", "苹果音乐"]
    if score_terms(title_lower, apple_services) > 0:
        return False
    if score_terms(
        title_lower,
        [
            "market report",
            "market forecast",
            "market size",
            "industry report",
            "industry forecast",
            "市场报告",
            "市场预测",
            "市场规模",
            "行业报告",
            "行业预测",
            "全球录制音乐市场",
        ],
    ) <= 0:
        return False
    if score_terms(lower, apple_services) <= 0:
        return False
    peer_services = [
        "spotify",
        "youtube music",
        "amazon music",
        "netflix",
        "disney+",
        "hulu",
        "腾讯音乐",
        "网易云音乐",
    ]
    if sum(1 for service in peer_services if service in lower) < 2:
        return False
    metric_terms = ["users", "subscribers", "share", "revenue", "growth", "用户", "订阅数", "份额", "收入", "增长"]
    for sentence in re.split(r"[。.!?！？\n]+", lower):
        if score_terms(sentence, apple_services) <= 0 or score_terms(sentence, metric_terms) <= 0:
            continue
        if sum(1 for service in peer_services if service in sentence) == 0 and re.search(r"\d", sentence):
            return False
    return True


def is_title_led_direct_apple_hardware_roadmap_story(title: str, text: str) -> bool:
    """Give the explicit Apple home-hub identity precedence over AI background."""
    identity = title_led_identity(title, text)
    title_lower = title.lower()
    lead_scope = title_and_lead_scope(title, text, limit=900).lower()
    editorial_home_hub_title = bool(
        score_terms(title_lower, ["apple", "苹果"]) > 0
        and score_terms(title_lower, ["screen", "display", "hub", "屏幕", "中枢", "siri"]) > 0
        and score_terms(lead_scope, ["home hub", "smart home hub", "家庭中枢", "智能家居中枢"]) > 0
    )
    return bool(
        identity.content_form == "news"
        and identity.scope == "apple-direct"
        and ("apple-home-hub" in identity.title_products or editorial_home_hub_title)
        and is_direct_apple_hardware_roadmap_story(text, title)
    )


def is_projected_apple_hardware_roadmap_story(title: str, text: str) -> bool:
    """Recognize the crawler's product-scoped projection contract."""
    if not re.fullmatch(r"apple\s+.+\s+roadmap\s+update", clean_sentence(title), re.I):
        return False
    identity = title_led_identity(title, text)
    return bool(
        identity.scope == "apple-direct"
        and identity.title_products
        & {
            "airpods",
            "apple-home-hub",
            "apple-tv",
            "apple-watch",
            "beats",
            "foldable-iphone",
            "homepod",
            "imac",
            "ipad",
            "iphone",
            "mac",
            "mac-mini",
            "mac-pro",
            "mac-studio",
            "macbook",
            "vision-pro",
        }
    )


def is_title_led_specific_future_apple_hardware_report(title: str, text: str) -> bool:
    """Keep a named, attributed future Apple model report in the hardware domain."""
    identity = title_led_identity(title, text)
    if identity.content_form != "news" or identity.scope != "apple-direct":
        return False
    hardware_products = {
        "airpods",
        "apple-watch",
        "beats",
        "homepod",
        "ipad",
        "ipad-air",
        "ipad-base",
        "ipad-mini",
        "ipad-pro",
        "iphone",
        "mac",
        "mac-mini",
        "mac-pro",
        "mac-studio",
        "macbook",
        "vision-pro",
    }
    if not (identity.title_products & hardware_products):
        return False
    specific_model = any(
        component.startswith(
            (
                "iphone-model:",
                "macbook-model:",
                "product-generation:",
                "display-size:",
            )
        )
        for component in identity.title_components
    ) or bool(
        identity.title_products
        & {"ipad-air", "ipad-base", "ipad-mini", "ipad-pro", "mac-mini", "mac-pro", "mac-studio"}
    )
    if not specific_model:
        return False
    if not any(
        component.startswith("report-attribution:")
        for component in identity.components
    ):
        return False
    return bool(
        identity.title_actions
        & {"delay-roadmap", "feature-change", "pilot-testing", "retail-availability", "supply-production"}
        or score_terms(
            title.lower(),
            [
                "expected",
                "reportedly",
                "rumored",
                "to feature",
                "to launch",
                "could feature",
                "may feature",
                "预计",
                "预估",
                "传闻",
                "消息称",
                "将配备",
                "将搭载",
                "将发布",
            ],
        )
        > 0
    )


def is_unsourced_editorial_hardware_inference_without_new_report(title: str, text: str) -> bool:
    """Recognize a publisher's product inference that explicitly lacks new sourcing."""
    identity = title_led_identity(title, text)
    if identity.scope != "apple-direct" or not hardware_product_families_from_text(title):
        return False
    scope = title_and_lead_scope(title, text, limit=2600).lower()
    no_report = score_terms(
        scope,
        [
            "no specific rumor",
            "no specific rumors",
            "no concrete rumor",
            "no concrete rumors",
            "without a specific report",
            "without new reporting",
            "without an independent source",
            "purely speculative",
            "具体细节尚未有确切传闻",
            "尚未有确切传闻",
            "没有确切传闻",
            "没有具体爆料",
            "没有提供独立消息源",
            "并无确切爆料",
            "纯属推测",
        ],
    ) > 0
    inference_score = score_terms(
        scope,
        [
            "there is a reasonable case",
            "the obvious candidate",
            "would be a suitable candidate",
            "it stands to reason",
            "if that happens",
            "if the mini receives",
            "有理由认为",
            "顺理成章",
            "不排除",
            "极有可能",
            "推测认为",
        ],
    )
    if no_report:
        return True
    attributed_report = score_terms(
        scope,
        [
            "according to",
            "new report",
            "reported today",
            "sources say",
            "analyst",
            "leaker",
            "据彭博",
            "据分析师",
            "消息人士",
            "最新报告",
            "今日透露",
        ],
    ) > 0
    schedule_title = score_terms(
        title.lower(),
        [
            "pre-orders",
            "preorders",
            "release date",
            "launch date",
            "发布日期",
            "发售日期",
            "预购日期",
        ],
    ) > 0
    official_schedule_missing = score_terms(
        scope,
        [
            "has yet to reveal",
            "has not revealed",
            "has yet to announce",
            "has not announced",
            "尚未公布",
            "尚未宣布",
            "尚未确认",
        ],
    ) > 0
    calendar_inference = score_terms(
        scope,
        [
            "familiar pattern",
            "historical pattern",
            "usual pattern",
            "most likely date",
            "until proven otherwise",
            "another possibility",
            "it is possible that",
            "would likely",
            "历年节奏",
            "历史规律",
            "最可能日期",
            "另一种可能",
            "推演",
        ],
    )
    if (
        schedule_title
        and official_schedule_missing
        and calendar_inference >= 2
        and not attributed_report
    ):
        return True
    historical_design_premise = bool(
        re.search(
            r"(?:looked|looks|remained|stayed)\s+(?:largely\s+)?(?:the\s+)?same\s+since|"
            r"longest-running\s+design|"
            r"自\s*20\d{2}\s*年(?:以来)?.{0,45}(?:外观|设计|模具).{0,30}(?:未变|没有变化|保持不变)|"
            r"(?:外观|设计|模具).{0,20}自\s*20\d{2}\s*年(?:以来)?.{0,30}(?:未变|没有变化|保持不变)|"
            r"连续.{0,20}(?:代|年).{0,30}(?:外观|设计|模具).{0,20}(?:未变|没有变化|沿用)",
            scope,
        )
    )
    tentative_projection = score_terms(
        scope,
        [
            "could change",
            "could be redesigned",
            "may change",
            "might change",
            "could finally",
            "有望",
            "可能会",
            "可能在明年",
            "或将改版",
        ],
    ) > 0
    primary_source = score_terms(
        scope,
        [
            "supply chain source",
            "sources familiar",
            "people familiar",
            "analyst",
            "investor note",
            "research note",
            "regulatory filing",
            "code reference",
            "供应链消息",
            "知情人士",
            "分析师",
            "研报",
            "监管文件",
            "代码显示",
        ],
    ) > 0
    return (inference_score >= 2 and not attributed_report) or (
        historical_design_premise and tentative_projection and not primary_source
    )


def is_single_user_apple_product_durability_anecdote_without_new_action(title: str, text: str) -> bool:
    """Keep one-owner accident anecdotes out of the required news queue."""
    identity = title_led_identity(title, text)
