def is_third_party_platform_app_launch_title(title: str) -> bool:
    lower = title.lower()
    platform_score = score_terms(
        lower,
        [
            "ios version",
            "ios app",
            "native ios app",
            "ipados app",
            "mac app",
            "macos app",
            "watchos app",
            "visionos app",
            "apple watch app",
            "app store",
            "ios 版",
            "ios版",
            "ipados 版",
            "ipados版",
            "mac 版",
            "mac版",
            "macos 版",
            "macos版",
            "watchos 版",
            "watchos版",
            "visionos 版",
            "visionos版",
            "苹果 ios 版",
            "苹果ios版",
            "苹果应用商店",
            "客户端",
            "应用",
            "app",
        ],
    )
    launch_score = score_terms(
        lower,
        [
            "launch",
            "launches",
            "launched",
            "available",
            "released",
            "rolls out",
            "lands",
            "comes to",
            "上线",
            "上架",
            "登陆",
            "登录",
            "发布",
            "推出",
            "适配",
        ],
    )
    if platform_score <= 0 or launch_score <= 0:
        return False
    third_party_subject_score = score_terms(
        lower,
        [
            "google",
            "microsoft",
            "meta",
            "openai",
            "chatgpt",
            "anthropic",
            "claude",
            "perplexity",
            "spotify",
            "netflix",
            "tencent",
            "wechat",
            "bytedance",
            "alibaba",
            "baidu",
            "xiaomi",
            "third-party",
            "third party",
            "谷歌",
            "微软",
            "腾讯",
            "微信",
            "字节",
            "阿里",
            "百度",
            "小米",
            "第三方",
        ],
    )
    quoted_app_subject = bool(
        re.search(r"(?:app|应用|客户端)\s*[“\"'][\w\u4e00-\u9fff -]{1,24}[”\"']", lower)
        or re.search(r"[“\"'][\w\u4e00-\u9fff -]{1,24}[”\"']\s*(?:app|应用|客户端)", lower)
    )
    leading_named_subject = bool(
        re.match(r"^[A-Za-z][A-Za-z0-9.+_-]{2,}\b", title)
        and not re.match(
            r"^(?:Apple|iPhone|iPad|Mac|macOS|iOS|iPadOS|watchOS|tvOS|visionOS)\b",
            title,
            re.I,
        )
    )
    if third_party_subject_score <= 0 and not quoted_app_subject and not leading_named_subject:
        return False
    if score_terms(
        lower,
        [
            "apple releases",
            "apple launches",
            "apple announces",
            "apple seeds",
            "apple rolls out",
            "苹果发布",
            "苹果推出",
            "苹果宣布",
            "苹果推送",
        ],
    ) > 0:
        return False
    return True


