def is_direct_apple_product_adoption_story(title: str, text: str) -> bool:
    """Identify concrete institutional adoption of a first-party Apple device."""
    identity = title_led_identity(title, text)
    if (
        identity.scope != "apple-direct"
        or identity.content_form != "news"
        or not identity.title_products
        & {
            "iphone",
            "ipad",
            "ipad-air",
            "ipad-base",
            "ipad-mini",
            "ipad-pro",
            "mac",
            "macbook",
            "apple-watch",
            "vision-pro",
        }
    ):
        return False
    scope = title_and_lead_scope(title, text, limit=1500).lower()
    if score_terms(
        title.lower(),
        [
            "launches new service",
            "launches a service",
            "service to manage",
            "management service",
            "device management",
            "推出新服务",
            "管理服务",
            "设备管理",
        ],
    ) > 0:
        return False
    institution = score_terms(
        scope,
        [
            "school",
            "schools",
            "school district",
            "k-12",
            "education market",
            "university",
            "universities",
            "enterprise",
            "enterprises",
            "organization",
            "organizations",
            "学校",
            "学区",
            "教育市场",
            "高校",
            "大学",
            "企业",
            "机构",
        ],
    ) > 0
    adoption = score_terms(
        scope,
        [
            "adopt",
            "adoption",
            "deploy",
            "deployment",
            "migrate to",
            "migrating to",
            "move to",
            "moving to",
            "replace",
            "replacing",
            "purchased",
            "bought",
            "roll out",
            "rolling out",
            "采用",
            "部署",
            "迁移至",
            "迁移到",
            "转向",
            "替换",
            "取代",
            "采购",
            "购买",
            "配发",
        ],
    ) > 0
    attributed = score_terms(
        scope,
        [
            "apple said",
            "apple says",
            "apple disclosed",
            "apple reported",
            "earnings call",
            "earnings conference call",
            "quarterly results",
            "苹果称",
            "苹果表示",
            "苹果披露",
            "苹果报告",
            "财报电话会议",
            "季度业绩",
        ],
    ) > 0
    measured = bool(
        re.search(
            r"(?i)\d[\d,.\s万千~～至到-]{0,16}"
            r"(?:units?|devices?|students?|employees?|schools?|台|名学生|名员工|所(?:学校|高中))",
            scope,
        )
    )
    return institution and adoption and (attributed or measured)


