def is_routine_crime_roundup_without_apple_action(title: str, text: str) -> bool:
    title_lower = clean_sentence(title).lower()
    if not (
        score_terms(title_lower, ["crime blotter", "crime roundup", "犯罪简报", "犯罪汇总"]) > 0
        or re.search(r"\bcrime[ -]?blotter\b|\bcrime[ -]?roundup\b", title_lower)
    ):
        return False
    return not (
        is_apple_product_legal_proceeding_story(title, text)
        or score_terms(
            title_lower,
            ["apple sues", "apple lawsuit", "apple files", "苹果起诉", "苹果诉", "苹果报案"],
        )
        > 0
    )


def is_multi_brand_comparison_led_market_story(title: str, text: str) -> bool:
    title_lower = title.lower()
    lower = text.lower()
    if effective_apple_term_score(title) <= 0:
        return False
    if score_terms(title_lower, ["counterpoint", "idc", "canalys", "omdia", "report", "报告", "机构"]) > 0:
        return False
    comparison_title = (
        score_terms(
            title_lower,
            [
                " vs ",
                "versus",
                "combined",
                "倍",
                "总和",
                "一款顶",
                "对比",
                "碾压",
                "吊打",
            ],
        )
        > 0
    )
    if not comparison_title:
        return False
    competitor_brands = [
        "samsung",
        "google",
        "pixel",
        "xiaomi",
        "huawei",
        "honor",
        "oppo",
        "vivo",
        "iqoo",
        "oneplus",
        "三星",
        "谷歌",
        "小米",
        "华为",
        "荣耀",
        "一加",
    ]
    brand_count = sum(1 for brand in competitor_brands if score_terms(lower, [brand]) > 0)
    return brand_count >= 2


def apple_chip_roadmap_facets_from_text(text: str) -> set[str]:
    if is_apple_chip_process_roadmap_story(text):
        return {"apple-chip-process-roadmap"}
    if not is_primary_apple_chip_roadmap_title(text):
        return set()
    families = hardware_product_families_from_text(text)
    facets: set[str] = set()
    if is_apple_m6_chip_roadmap_story(text):
        facets.add("apple-m6-chip-roadmap")
    if "mac" in families:
        facets.add("mac-chip-roadmap")
    if "iphone" in families:
        facets.add("iphone-chip-roadmap")
    if "ipad" in families:
        facets.add("ipad-chip-roadmap")
    if not facets:
        facets.add("apple-chip-roadmap")
    return facets


