def os_internal_testing_identity_facets(
    title_facets: set[str], combined_facets: set[str]
) -> set[str]:
    versions = os_release_version_facets(title_facets) or os_release_version_facets(combined_facets)
    platforms = merge_guard_platform_facets(title_facets) or merge_guard_platform_facets(combined_facets)
    return {"os-internal-testing"} | versions | platforms


def _primary_topic_facets(title: str, summary: str = "") -> frozenset[str]:
    title_facets = topic_facets_from_text(title)
    combined_text = title_and_lead_scope(title, summary, limit=1200)
    combined_facets = topic_facets_from_text(combined_text)
    title_has_china_ai_action = is_apple_intelligence_china_regulatory_rollout_story(title, title)
    if not title_has_china_ai_action:
        combined_facets.discard("apple-intelligence-china-regulatory-rollout")
    if not is_apple_sales_tax_holiday_story(title, combined_text):
        combined_facets.discard("apple-sales-tax-holiday")
    if is_russia_fas_app_preinstall_regulation_story(combined_text):
        # Keep the title-led Russian preinstallation action ahead of historical
        # App Store removals or other regulatory background in the body.
        return frozenset({"russia-fas-app-preinstall-regulation"})
    for predicate, facet in (
        (is_apple_hardware_leadership_personnel_story, "apple-hardware-leadership-personnel"),
        (is_icloud_post_employment_file_access_story, "icloud-post-employment-file-access"),
        (is_apple_security_report_submission_quota_story, "apple-security-report-submission-quota"),
        (is_uk_icloud_backdoor_legal_challenge_story, "uk-icloud-backdoor-legal-challenge"),
        (is_direct_apple_ai_service_cost_policy_story, "apple-ai-service-cost-policy"),
        (is_official_apple_accessories_page_update_story, "apple-official-accessories-page"),
        (is_apple_cross_device_clipboard_interop_story, "apple-cross-device-clipboard"),
        (is_direct_third_party_apple_data_integration_story, "apple-health-data-sync"),
        (is_app_store_delisting_or_restoration_story, "app-store-delisting-restoration"),
    ):
        if predicate(title, combined_text):
            return frozenset({facet})
    if is_india_tariff_iphone_manufacturing_story(combined_text):
        return frozenset({"india-tariff-iphone-manufacturing"})
    if is_apple_smart_glasses_health_platform_story(title, combined_text):
        return frozenset({"apple-smart-glasses-health-platform"})
    if is_title_led_apple_product_supply_constraint_story(title, combined_text):
        if is_apple_memory_supply_constraint_story(combined_text):
            return frozenset(
                {"apple-product-supply-constraint", "apple-memory-supply-constraint"}
            )
        return frozenset({"apple-product-supply-constraint"})
    if is_title_led_iphone_component_cost_forecast_story(title, combined_text):
        return frozenset({"iphone-component-cost-forecast"})
    if "macbook-thermal-defect" in (title_facets | combined_facets):
        return frozenset({"macbook-thermal-defect"})
    if is_apple_silicon_third_party_os_driver_compatibility_story(title, combined_text):
        return frozenset({"apple-silicon-os-driver-compatibility"})
    if is_direct_apple_smart_glasses_roadmap_story(title, combined_text):
        return frozenset({"apple-smart-glasses-roadmap"})
    if (
        score_terms(title.lower(), ["apple watch", "苹果手表"]) > 0
        and is_apple_watch_redesign_story(combined_text)
        and not is_apple_watch_band_sensor_story(title)
    ):
        return frozenset({"apple-watch-redesign"})
    if is_direct_apple_regulatory_trade_action_story(title, combined_text):
        return frozenset({"apple-regulatory-trade-action"})
    if is_apple_display_supplier_price_negotiation_story(title, combined_text):
        return frozenset({"apple-display-panel-price-negotiation"})
    if is_direct_apple_facility_incident_story(title, combined_text):
        return frozenset({"apple-facility-incident"})
    if is_direct_apple_financial_results_story(title, combined_text):
        return frozenset({"apple-financial-results"})
    if is_apple_platform_executable_replacement_attack_story(title, combined_text):
        return frozenset({"apple-platform-executable-replacement-attack"})
    if is_siri_ai_lawsuit_settlement_story(combined_text):
        return frozenset({"siri-ai-lawsuit-settlement"})
    if title_has_china_ai_action:
        return frozenset({"apple-intelligence-china-regulatory-rollout"})
    if is_title_primary_siri_ai_availability_story(title):
        release_facets = os_release_facets_from_text(title)
        return frozenset({"apple-ai-platform"} | release_facets)
    if is_apple_device_carrier_lock_policy_story(title, combined_text):
        return frozenset({"iphone-carrier-lock-policy"})
    if is_official_apple_education_promotion_story(title, combined_text):
        return frozenset({"apple-education-promotion"})
    if is_applecare_plan_price_change_story(title, combined_text):
        return frozenset({"applecare-plan-price-change"})
    if is_ipad_carrier_financing_story(title, combined_text):
        return frozenset({"ipad-carrier-financing"})
    if is_apple_ai_chip_acquisition_story(title, combined_text):
        return frozenset({"apple-ai-chip-acquisition"})
    if is_apple_maps_ad_policy_story(title, combined_text):
        return frozenset({"apple-maps-ad-policy"})
    if is_brazil_minor_gambling_app_inquiry_story(title, combined_text):
        return frozenset({"app-store-minor-gambling-inquiry"})
    if is_apple_sales_tax_holiday_story(title, combined_text):
        return frozenset({"apple-sales-tax-holiday"})
    if is_apple_supplier_commercial_outlook_story(title, combined_text):
        return frozenset({"apple-supplier-commercial-outlook"})
    if is_legal_case_person_profile_without_new_action(title, combined_text):
        return frozenset({"legal-case-person-profile"})
    if is_supplier_wealth_profile_without_new_apple_action(title, combined_text):
        return frozenset({"supplier-person-wealth-profile"})
    if is_apple_analyst_rating_target_story(title, combined_text):
        return frozenset({"apple-analyst-rating-target"})
    title_primary_legal = is_title_primary_apple_legal_proceeding_story(title, combined_text)
    if not title_primary_legal:
        combined_facets = {
            facet
            for facet in combined_facets
            if facet
            not in {
                "apple-legal-proceeding",
                "apple-hardware-trade-secret-lawsuit",
                "epic-app-store-appeal",
                "icloud-child-safety-lawsuit",
                "airpods-max-condensation-lawsuit",
            }
            and not facet.startswith("legal-counterparty-")
        }
    if not (
        score_terms(title.lower(), ["apple tv", "apple tv+", "苹果电视"]) > 0
        and score_terms(title.lower(), ["trailer", "teaser", "first look", "预告", "先导"]) > 0
    ):
        combined_facets.discard("apple-tv-content-trailer")
    if not is_apple_strategic_transaction_story(title):
        combined_facets -= {
            facet
            for facet in combined_facets
            if facet == "apple-strategic-transaction" or facet.startswith("transaction-counterparty-")
        }
    if (
        "apple-market-share-report" in combined_facets
        and not is_apple_specific_market_share_report_story(combined_text, title)
    ):
        combined_facets.discard("apple-market-share-report")
    if is_title_primary_apple_market_share_story(title, combined_text):
        return frozenset({"apple-market-share-report"})
    if is_title_primary_apple_product_production_forecast_story(title, combined_text):
        return frozenset({"apple-product-production-forecast"})
    if is_direct_apple_chip_foundry_sourcing_story(title, combined_text):
        return frozenset({"apple-chip-foundry-sourcing"})
    if is_non_apple_component_market_background_story(title, combined_text):
        return frozenset({"non-apple-component-market-background"})
    if is_direct_apple_first_party_developer_guidance_story(title, combined_text):
        return frozenset({"apple-developer-guidance"})
    if is_apple_cross_device_pairing_api_story(title, combined_text):
        return frozenset({"apple-cross-device-pairing-api"})
    if is_material_apple_stock_move_story(title, combined_text):
        return frozenset({"apple-material-stock-move"})
    legal_counterparties = legal_case_counterparty_facets(title) if title_primary_legal else set()
    legal_subjects = legal_case_subject_facets(combined_text) if title_primary_legal else set()
    if legal_counterparties or legal_subjects:
        legal_facets = {"apple-legal-proceeding", *legal_counterparties, *legal_subjects}
        if is_hardware_focused_apple_legal_story(title, combined_text):
            legal_facets.add("apple-hardware-trade-secret-lawsuit")
        return frozenset(legal_facets)
    if is_direct_apple_platform_malware_report_story(title, combined_text):
        return frozenset({"mac-malware-threat"} | malware_family_facets(title, combined_text))
    if is_direct_messages_malicious_content_warning_story(title, combined_text):
        return frozenset({"messages-malicious-content-warning"})
    if is_apple_vintage_hardware_auction_story(title, combined_text):
        return frozenset({"apple-vintage-hardware-auction"})
    if title_primary_legal and is_hardware_focused_apple_legal_story(title, combined_text):
        return frozenset({"apple-legal-proceeding", "apple-hardware-trade-secret-lawsuit"})
    if is_apple_strategic_transaction_story(title):
        transaction_facets = {
            facet
            for facet in combined_facets
            if facet == "apple-strategic-transaction" or facet.startswith("transaction-counterparty-")
        }
        return frozenset(transaction_facets or {"apple-strategic-transaction"})
    if is_direct_apple_airpods_firmware_story(title, combined_text):
        return frozenset({"airpods-firmware"})
    signing_facets = (title_facets | combined_facets) & (
        {"ios-signing-status"} | os_release_version_facets(title_facets | combined_facets) | merge_guard_platform_facets(title_facets | combined_facets)
    )
    if "ios-signing-status" in signing_facets:
        return frozenset(signing_facets)
    if is_os_point_release_internal_testing_story(combined_text):
        return frozenset(os_internal_testing_identity_facets(title_facets, combined_facets))
    if (is_os_release_availability_title(title) or is_current_public_beta_release_title(title)) and (
        is_current_public_beta_release_title(title)
        or not os_release_title_specific_facets_from_title(title)
    ):
        title_release_facets = os_release_facets_from_text(title) or os_release_facets_from_text(combined_text)
        if title_release_facets:
            return frozenset(title_release_facets)
    camera_airpods_facets = combined_facets & {"camera-airpods-code-clue", "camera-airpods-development-suspension"}
    if camera_airpods_facets:
        if "camera-airpods-code-clue" in title_facets:
            return frozenset({"camera-airpods-code-clue"})
        if "camera-airpods-development-suspension" in title_facets:
            return frozenset({"camera-airpods-development-suspension"})
        if "camera-airpods-code-clue" in camera_airpods_facets and score_terms(
            f"{title} {summary}".lower(),
            ["b790", "code", "developer beta", "system_prompt", "代码", "开发者测试版"],
        ) > 0:
            return frozenset({"camera-airpods-code-clue"})
        return frozenset(camera_airpods_facets)
    if is_apple_retail_device_deployment_story(title, combined_text):
        return frozenset({"apple-retail-device-deployment"})
    if is_apple_pencil_product_roadmap_story(title, combined_text):
        return frozenset({"apple-pencil-product-roadmap"})
    if is_apple_m6_generation_transition_story(title, combined_text):
        return frozenset({"apple-m6-chip-roadmap"})
    if is_apple_chip_memory_capacity_story(title, combined_text):
        return frozenset({"apple-chip-memory-capacity"})
    if is_apple_chip_research_transfer_story(title, combined_text):
        return frozenset({"apple-chip-research-transfer"})
    if is_apple_chip_tariff_exemption_story(title, combined_text):
        return frozenset({"apple-chip-tariff-exemption"})
    if is_apple_device_battery_regulation_story(combined_text):
        return frozenset({"apple-device-battery-regulation"})
    if (
        is_direct_apple_regulated_technology_access_story(title, combined_text)
        and not is_apple_restricted_memory_supplier_approval_story(combined_text)
        and not is_apple_memory_supplier_sourcing_story(combined_text)
    ):
        return frozenset({"apple-regulated-technology-access"})
    if "apple-legal-proceeding" in title_facets:
        legal_specific = title_facets & SPLITTABLE_POLICY_TOPIC_FACETS
        return frozenset(legal_specific or {"apple-legal-proceeding"})
    if "iphone-memory-feature-support" in combined_facets:
        return frozenset({"iphone-memory-feature-support"})
    if is_direct_apple_os_component_change_story(title, combined_text):
        specific_facets = combined_facets & (EXACT_SHARED_EVENT_TOPIC_FACETS | APP_STORE_POLICY_SUBTOPIC_FACETS)
        if specific_facets:
            return frozenset(specific_facets | merge_guard_platform_facets(combined_facets))
        software_facets = (
            title_facets
            - SOFTWARE_SUMMARY_HARDWARE_NOISE_FACETS
            - {"apple-product-data-leak", "apple-product-data-leak-enforcement", "apple-product-data-leak-specs"}
        )
        meaningful_facets = software_facets - {"built-in-app-change"} - merge_guard_platform_facets(software_facets)
        if meaningful_facets:
            software_facets.discard("built-in-app-change")
        else:
            software_facets.add("built-in-app-change")
        return frozenset(software_facets)
    if is_apple_hardware_production_retooling_story(title, combined_text):
        return frozenset({"apple-hardware-production-retooling"})
    if is_apple_display_panel_spec_rumor_story(title, combined_text):
        return frozenset({"apple-display-panel-spec-rumor"})
    title_product_roadmap_facets = title_scoped_hardware_product_roadmap_facets(title)
    if title_product_roadmap_facets:
        return frozenset(title_product_roadmap_facets | (title_facets - BROAD_TOPIC_FACETS))
    title_foldable_production_facets = title_scoped_foldable_iphone_production_facets(title)
    if title_foldable_production_facets:
        return frozenset(title_foldable_production_facets | (title_facets - BROAD_TOPIC_FACETS))
    if "iphone-memory-feature-support" in combined_facets:
        return frozenset({"iphone-memory-feature-support"})
    memory_supplier_facets = combined_facets & {
        "apple-restricted-memory-supplier-approval",
        "apple-memory-supplier-sourcing",
    }
    if memory_supplier_facets:
        return frozenset(memory_supplier_facets)
    if "apple-product-price-increase" in title_facets:
        combined_price_details = price_detail_facets(combined_facets)
        title_price_details = price_detail_facets(title_facets)
        if combined_price_details and not title_price_details:
            return frozenset(title_facets | combined_price_details)
        return frozenset(title_facets)
    exact_shared_facets = combined_facets & EXACT_SHARED_EVENT_TOPIC_FACETS
    if exact_shared_facets:
        return frozenset(exact_shared_facets | merge_guard_platform_facets(combined_facets))
    if is_apple_os_feature_or_summary_story(combined_text) and is_title_primary_software_system_story(title, combined_text):
        software_facets = os_feature_specific_facets(combined_facets - SOFTWARE_SUMMARY_HARDWARE_NOISE_FACETS)
        if software_facets:
            return frozenset(software_facets)
    if is_iphone_physical_dimension_rumor_story(title, combined_text):
        return frozenset({"iphone-physical-dimension-rumor"})
    data_leak_detail_facets = {"apple-product-data-leak-enforcement", "apple-product-data-leak-specs"}
    if "apple-product-data-leak-enforcement" in title_facets:
        enforcement_facets = title_facets - DATA_LEAK_ENFORCEMENT_OBJECT_FACETS
        return frozenset(enforcement_facets or title_facets)
    if title_facets & TITLE_DOMINANT_TOPIC_FACETS:
        dominant_facets = title_facets - data_leak_detail_facets - {"apple-product-data-leak"}
        return frozenset(dominant_facets or title_facets)
    if (
        is_apple_chip_process_roadmap_story(combined_text)
        and score_terms(
            title.lower(),
            ["14a", "18a", "18a-p", "intel", "tsmc", "foundry", "英特尔", "台积电", "制程", "工艺", "代工订单", "代工协议", "代工合作"],
        )
        > 0
    ):
        return frozenset({"apple-chip-process-roadmap"})
    if title_facets & data_leak_detail_facets:
        return frozenset(title_facets)
    if combined_facets & data_leak_detail_facets:
        return frozenset(combined_facets)
    if "apple-creator-studio" in title_facets:
        return frozenset(title_facets)
    if "apple-arcade" in combined_facets and score_terms(
        combined_text.lower(),
        ["arcade edition", "apple arcade", "苹果 arcade", "登陆苹果 arcade"],
    ) > 0:
        return frozenset({"apple-arcade"})
    if "final-cut-camera-update" in combined_facets:
        return frozenset({"final-cut-camera-update"})
    if "app-store-policy" in title_facets and "brazil-app-store-policy" in combined_facets:
        return frozenset(combined_facets)
    if combined_facets & APP_STORE_POLICY_SUBTOPIC_FACETS:
        return frozenset(combined_facets)
    if "visionos-m5-ai-features" in combined_facets:
        return frozenset(combined_facets)
    if "iphone-component-cost-forecast" in combined_facets:
        return frozenset(
            {"iphone-component-cost-forecast"}
            | (combined_facets & {"apple-product-price-increase", "apple-future-product-price-forecast"})
        )
    market_report_primary = (
        "apple-market-share-report" in combined_facets
        and "apple-product-price-increase" not in title_facets
        and not is_foldable_iphone_panel_market_report_context(combined_text)
        and (
            is_apple_specific_market_share_report_story(title, "")
            or ("apple-product-price-increase" not in title_facets and is_apple_specific_market_share_report_story(combined_text, title))
        )
    )
    if market_report_primary:
        return frozenset({"apple-market-share-report"} | merge_guard_platform_facets(combined_facets))
    if title_facets and (title_facets - BROAD_TOPIC_FACETS):
        return frozenset(title_facets)
    return frozenset(combined_facets or title_facets)


@lru_cache(maxsize=16384)
def cached_primary_topic_facets(title: str, summary: str = "") -> frozenset[str]:
    return _primary_topic_facets(title, summary)


def primary_topic_facets(title: str, summary: str = "") -> set[str]:
    return set(cached_primary_topic_facets(title, summary))


def _primary_merge_guard_facets(title: str, summary: str = "") -> frozenset[str]:
    title_facets = merge_guard_facets_from_text(title)
    combined_text = title_and_lead_scope(title, summary, limit=1200)
    combined_facets = merge_guard_facets_from_text(combined_text)
    title_has_china_ai_action = is_apple_intelligence_china_regulatory_rollout_story(title, title)
    if not title_has_china_ai_action:
        combined_facets.discard("apple-intelligence-china-regulatory-rollout")
    if not is_apple_sales_tax_holiday_story(title, combined_text):
        combined_facets.discard("apple-sales-tax-holiday")
    for predicate, facet in (
        (is_apple_hardware_leadership_personnel_story, "apple-hardware-leadership-personnel"),
        (is_icloud_post_employment_file_access_story, "icloud-post-employment-file-access"),
        (is_apple_security_report_submission_quota_story, "apple-security-report-submission-quota"),
        (is_uk_icloud_backdoor_legal_challenge_story, "uk-icloud-backdoor-legal-challenge"),
        (is_direct_apple_ai_service_cost_policy_story, "apple-ai-service-cost-policy"),
    ):
        if predicate(title, combined_text):
            return frozenset({facet})
    if is_india_tariff_iphone_manufacturing_story(combined_text):
        return frozenset({"india-tariff-iphone-manufacturing"})
    if is_apple_smart_glasses_health_platform_story(title, combined_text):
        return frozenset({"apple-smart-glasses-health-platform"})
    if is_title_led_apple_product_supply_constraint_story(title, combined_text):
        if is_apple_memory_supply_constraint_story(combined_text):
            return frozenset(
                {"apple-product-supply-constraint", "apple-memory-supply-constraint"}
            )
        return frozenset({"apple-product-supply-constraint"})
    if is_title_led_iphone_component_cost_forecast_story(title, combined_text):
        return frozenset({"iphone-component-cost-forecast"})
    if "macbook-thermal-defect" in (title_facets | combined_facets):
        return frozenset({"macbook-thermal-defect"})
    if title_has_china_ai_action:
        return frozenset({"apple-intelligence-china-regulatory-rollout"})
    if is_title_primary_siri_ai_availability_story(title):
        release_facets = os_release_facets_from_text(title)
        return frozenset({"apple-ai-platform"} | release_facets)
    if is_apple_device_carrier_lock_policy_story(title, combined_text):
        return frozenset({"iphone-carrier-lock-policy"})
    if is_official_apple_education_promotion_story(title, combined_text):
        return frozenset({"apple-education-promotion"})
    if is_applecare_plan_price_change_story(title, combined_text):
        return frozenset({"applecare-plan-price-change"})
    if is_ipad_carrier_financing_story(title, combined_text):
        return frozenset({"ipad-carrier-financing"})
    if is_apple_ai_chip_acquisition_story(title, combined_text):
        return frozenset({"apple-ai-chip-acquisition"})
    if is_apple_maps_ad_policy_story(title, combined_text):
        return frozenset({"apple-maps-ad-policy"})
    if is_brazil_minor_gambling_app_inquiry_story(title, combined_text):
        return frozenset({"app-store-minor-gambling-inquiry"})
    if is_apple_sales_tax_holiday_story(title, combined_text):
        return frozenset({"apple-sales-tax-holiday"})
    if is_apple_supplier_commercial_outlook_story(title, combined_text):
        return frozenset({"apple-supplier-commercial-outlook"})
    if is_legal_case_person_profile_without_new_action(title, combined_text):
        return frozenset({"legal-case-person-profile"})
    if is_supplier_wealth_profile_without_new_apple_action(title, combined_text):
        return frozenset({"supplier-person-wealth-profile"})
    if is_apple_analyst_rating_target_story(title, combined_text):
        return frozenset({"apple-analyst-rating-target"})
    title_primary_legal = is_title_primary_apple_legal_proceeding_story(title, combined_text)
    if not title_primary_legal:
        combined_facets = {
            facet
            for facet in combined_facets
            if facet
            not in {
                "apple-legal-proceeding",
                "apple-hardware-trade-secret-lawsuit",
                "epic-app-store-appeal",
                "icloud-child-safety-lawsuit",
                "airpods-max-condensation-lawsuit",
            }
            and not facet.startswith("legal-counterparty-")
        }
    if not (
        score_terms(title.lower(), ["apple tv", "apple tv+", "苹果电视"]) > 0
        and score_terms(title.lower(), ["trailer", "teaser", "first look", "预告", "先导"]) > 0
    ):
        combined_facets.discard("apple-tv-content-trailer")
    if not is_apple_strategic_transaction_story(title):
        combined_facets -= {
            facet
            for facet in combined_facets
            if facet == "apple-strategic-transaction" or facet.startswith("transaction-counterparty-")
        }
    if (
        "apple-market-share-report" in combined_facets
        and not is_apple_specific_market_share_report_story(combined_text, title)
    ):
        combined_facets.discard("apple-market-share-report")
    if is_title_primary_apple_market_share_story(title, combined_text):
        return frozenset({"apple-market-share-report"})
    if is_direct_apple_chip_foundry_sourcing_story(title, combined_text):
        return frozenset({"apple-chip-foundry-sourcing"})
    if is_non_apple_component_market_background_story(title, combined_text):
        return frozenset({"non-apple-component-market-background"})
    if is_direct_apple_first_party_developer_guidance_story(title, combined_text):
        return frozenset({"apple-developer-guidance"})
    if is_apple_cross_device_pairing_api_story(title, combined_text):
        return frozenset({"apple-cross-device-pairing-api"})
    if is_material_apple_stock_move_story(title, combined_text):
        return frozenset({"apple-material-stock-move"})
    legal_counterparties = legal_case_counterparty_facets(title) if title_primary_legal else set()
    legal_subjects = legal_case_subject_facets(combined_text) if title_primary_legal else set()
    if legal_counterparties or legal_subjects:
        legal_facets = {"apple-legal-proceeding", *legal_counterparties, *legal_subjects}
        if is_hardware_focused_apple_legal_story(title, combined_text):
            legal_facets.add("apple-hardware-trade-secret-lawsuit")
        return frozenset(legal_facets)
    if is_direct_apple_platform_malware_report_story(title, combined_text):
        return frozenset({"mac-malware-threat"} | malware_family_facets(title, combined_text))
    if is_direct_messages_malicious_content_warning_story(title, combined_text):
        return frozenset({"messages-malicious-content-warning"})
    if is_apple_vintage_hardware_auction_story(title, combined_text):
        return frozenset({"apple-vintage-hardware-auction"})
    if title_primary_legal and is_hardware_focused_apple_legal_story(title, combined_text):
        return frozenset({"apple-legal-proceeding", "apple-hardware-trade-secret-lawsuit"})
    if is_apple_strategic_transaction_story(title):
        transaction_facets = {
            facet
            for facet in combined_facets
            if facet == "apple-strategic-transaction" or facet.startswith("transaction-counterparty-")
        }
        return frozenset(transaction_facets or {"apple-strategic-transaction"})
    if is_direct_apple_airpods_firmware_story(title, combined_text):
        return frozenset({"airpods-firmware"})
    signing_facets = (title_facets | combined_facets) & (
        {"ios-signing-status"} | os_release_version_facets(title_facets | combined_facets) | merge_guard_platform_facets(title_facets | combined_facets)
    )
    if "ios-signing-status" in signing_facets:
        return frozenset(signing_facets)
    if is_os_point_release_internal_testing_story(combined_text):
        return frozenset(os_internal_testing_identity_facets(title_facets, combined_facets))
    if (is_os_release_availability_title(title) or is_current_public_beta_release_title(title)) and (
        is_current_public_beta_release_title(title)
        or not os_release_title_specific_facets_from_title(title)
    ):
        title_release_facets = os_release_facets_from_text(title) or os_release_facets_from_text(combined_text)
        if title_release_facets:
            return frozenset(title_release_facets)
    camera_airpods_facets = combined_facets & {"camera-airpods-code-clue", "camera-airpods-development-suspension"}
    if camera_airpods_facets:
        if "camera-airpods-code-clue" in title_facets:
            return frozenset({"camera-airpods-code-clue"})
        if "camera-airpods-development-suspension" in title_facets:
            return frozenset({"camera-airpods-development-suspension"})
        if "camera-airpods-code-clue" in camera_airpods_facets and score_terms(
            f"{title} {summary}".lower(),
            ["b790", "code", "developer beta", "system_prompt", "代码", "开发者测试版"],
        ) > 0:
            return frozenset({"camera-airpods-code-clue"})
        return frozenset(camera_airpods_facets)
    if is_apple_retail_device_deployment_story(title, combined_text):
        return frozenset({"apple-retail-device-deployment"})
    if is_apple_pencil_product_roadmap_story(title, combined_text):
        return frozenset({"apple-pencil-product-roadmap"})
    if is_apple_m6_generation_transition_story(title, combined_text):
        return frozenset({"apple-m6-chip-roadmap"})
    if is_apple_chip_memory_capacity_story(title, combined_text):
        return frozenset({"apple-chip-memory-capacity"})
    if is_apple_chip_research_transfer_story(title, combined_text):
        return frozenset({"apple-chip-research-transfer"})
    if is_apple_chip_tariff_exemption_story(title, combined_text):
        return frozenset({"apple-chip-tariff-exemption"})
    if is_apple_device_battery_regulation_story(combined_text):
        return frozenset({"apple-device-battery-regulation"})
    if (
        is_direct_apple_regulated_technology_access_story(title, combined_text)
        and not is_apple_restricted_memory_supplier_approval_story(combined_text)
        and not is_apple_memory_supplier_sourcing_story(combined_text)
    ):
        return frozenset({"apple-regulated-technology-access"})
    if "apple-legal-proceeding" in title_facets:
        legal_specific = title_facets & SPLITTABLE_POLICY_TOPIC_FACETS
        return frozenset(legal_specific or {"apple-legal-proceeding"})
    if "iphone-memory-feature-support" in combined_facets:
        return frozenset({"iphone-memory-feature-support"} | merge_guard_platform_facets(combined_facets))
    if is_direct_apple_os_component_change_story(title, combined_text):
        specific_facets = combined_facets & (EXACT_SHARED_EVENT_TOPIC_FACETS | APP_STORE_POLICY_SUBTOPIC_FACETS)
        if specific_facets:
            return frozenset(specific_facets | merge_guard_platform_facets(combined_facets))
        software_facets = (
            title_facets
            - SOFTWARE_SUMMARY_HARDWARE_NOISE_FACETS
            - {"apple-product-data-leak", "apple-product-data-leak-enforcement", "apple-product-data-leak-specs"}
        )
        meaningful_facets = software_facets - {"built-in-app-change"} - merge_guard_platform_facets(software_facets)
        if meaningful_facets:
            software_facets.discard("built-in-app-change")
        else:
            software_facets.add("built-in-app-change")
        return frozenset(software_facets)
    if is_apple_hardware_production_retooling_story(title, combined_text):
        return frozenset({"apple-hardware-production-retooling"})
    if is_apple_display_panel_spec_rumor_story(title, combined_text):
        return frozenset({"apple-display-panel-spec-rumor"})
    title_product_roadmap_facets = title_scoped_hardware_product_roadmap_facets(title)
    if title_product_roadmap_facets:
        return frozenset(title_product_roadmap_facets | (title_facets - BROAD_TOPIC_FACETS))
    title_foldable_production_facets = title_scoped_foldable_iphone_production_facets(title)
    if title_foldable_production_facets:
        return frozenset(title_foldable_production_facets | (title_facets - BROAD_TOPIC_FACETS))
    if "iphone-memory-feature-support" in combined_facets:
        return frozenset({"iphone-memory-feature-support"} | merge_guard_platform_facets(combined_facets))
    if "apple-restricted-memory-supplier-approval" in combined_facets or "apple-memory-supplier-sourcing" in combined_facets:
        return frozenset(combined_facets)
    if "apple-product-price-increase" in title_facets:
        combined_price_details = price_detail_facets(combined_facets)
        title_price_details = price_detail_facets(title_facets)
        if combined_price_details and not title_price_details:
            return frozenset(title_facets | combined_price_details)
        return frozenset(title_facets)
    exact_shared_facets = combined_facets & EXACT_SHARED_EVENT_TOPIC_FACETS
    if exact_shared_facets:
        return frozenset(exact_shared_facets | merge_guard_platform_facets(combined_facets))
    if is_apple_os_feature_or_summary_story(combined_text) and is_title_primary_software_system_story(title, combined_text):
        software_facets = os_feature_specific_facets(combined_facets - SOFTWARE_SUMMARY_HARDWARE_NOISE_FACETS)
        if software_facets:
            return frozenset(software_facets)
    if is_iphone_physical_dimension_rumor_story(title, combined_text):
        return frozenset({"iphone-physical-dimension-rumor"} | merge_guard_platform_facets(combined_facets))
    if "apple-creator-studio" in title_facets:
        return frozenset(title_facets)
    if "apple-arcade" in combined_facets and score_terms(
        combined_text.lower(),
        ["arcade edition", "apple arcade", "苹果 arcade", "登陆苹果 arcade"],
    ) > 0:
        return frozenset({"apple-arcade"})
    if "final-cut-camera-update" in combined_facets:
        return frozenset({"final-cut-camera-update"})
    if "iphone-component-cost-forecast" in combined_facets:
        return frozenset({"iphone-component-cost-forecast"} | merge_guard_platform_facets(combined_facets))
    if "apple-watch-band-sensor-rumor" in combined_facets:
        return frozenset({"apple-watch-band-sensor-rumor"} | merge_guard_platform_facets(combined_facets))
    if (
        is_apple_chip_process_roadmap_story(combined_text)
        and score_terms(
            title.lower(),
            ["14a", "18a", "18a-p", "intel", "tsmc", "foundry", "英特尔", "台积电", "制程", "工艺", "代工订单", "代工协议", "代工合作"],
        )
        > 0
    ):
        return frozenset({"apple-chip-process-roadmap"})
    if title_facets and merge_guard_action_facets(title_facets):
        return frozenset(title_facets)
    return frozenset(combined_facets or title_facets)


@lru_cache(maxsize=16384)
def cached_primary_merge_guard_facets(title: str, summary: str = "") -> frozenset[str]:
    return _primary_merge_guard_facets(title, summary)


def primary_merge_guard_facets(title: str, summary: str = "") -> set[str]:
    return set(cached_primary_merge_guard_facets(title, summary))


@lru_cache(maxsize=16384)
def cached_article_primary_facets(
    title: str,
    summary: str,
    key_facts: tuple[str, ...],
) -> frozenset[str]:
    facets = primary_topic_facets(title, summary)
    if is_multi_product_official_refurbished_story(title, summary):
        facets.add("apple-refurbished-product")
    # Event identity is title-led. Long summaries can introduce unrelated
    # feature facets, but they must not erase the release train stated in the
    # headline.
    facets |= os_release_facets_from_text(title)
    facets |= os_release_lead_identity_facets(title, summary)
    legal_scope = " ".join((title, summary, *key_facts[:8]))
    if is_direct_apple_ai_service_cost_policy_story(title, legal_scope):
        return frozenset({"apple-ai-service-cost-policy"})
    if is_title_primary_apple_legal_proceeding_story(
        title,
        f"{title} {summary[:1200]}",
    ):
        facets |= legal_case_subject_facets(legal_scope)
    if (
        is_os_release_availability_title(title)
        and not os_release_title_specific_facets_from_title(title)
        and not (
            facets
            & {
                "os-release-beta",
                "os-release-public-beta",
                "os-release-developer-beta",
                "os-release-revised-build",
                "os-release-rc",
            }
        )
    ):
        facets.add("os-release-final")
    detail_scope = " ".join((summary[:320], *key_facts[:2])).lower()
    detail_declares_current_rc = bool(
        re.search(
            r"\b(?:the\s+)?(?:rc|release candidate)(?:\s+(?:developer\s+)?betas?|\s+builds?)?\s+"
            r"(?:landed|arrived|released|rolled out|surfaced|seeded)\b|"
            r"(?:发布候选版|候选版构建).{0,20}(?:发布|推送|上线|到来)",
            detail_scope,
        )
    )
    if detail_declares_current_rc and os_release_version_facets(facets):
        facets = {
            facet
            for facet in facets
            if facet
            not in {
                "os-release-beta",
                "os-release-public-beta",
                "os-release-developer-beta",
            }
            and not re.fullmatch(r"os-release-beta-\d+", facet)
        }
        facets.add("os-release-rc")
    article_context = " ".join((title, summary, *key_facts))
    if (
        not is_foldable_iphone_panel_market_report_context(article_context)
        and not is_non_apple_component_market_background_story(title, article_context)
        and is_multi_vendor_market_report_with_material_apple_metrics(
            " ".join((summary, *key_facts)),
            title,
        )
    ):
        facets.add("apple-market-share-report")
    title_identity = build_event_identity(title, summary[:260])
    title_primary_intents = {
        component
        for component in title_identity.title_components
        if component.startswith("primary-intent:")
    }
    market_share_incompatible_intents = {
        "primary-intent:analyst-target",
        "primary-intent:capital-strategy",
        "primary-intent:compute-capacity-risk",
        "primary-intent:executive-retrospective",
        "primary-intent:market-move",
        "primary-intent:memory-supplier-policy",
        "primary-intent:product-supply-constraint",
    }
    if title_primary_intents & market_share_incompatible_intents:
        facets.discard("apple-market-share-report")
    if "apple-financial-results" in facets:
        facets.discard("apple-market-share-report")
    if (
        title_identity.title_products
        and "hardware-market-performance" in title_identity.title_components
        and not is_apple_specific_market_share_report_story(title, "")
    ):
        facets.discard("apple-market-share-report")
        facets.add("apple-product-sales-performance")
    return frozenset(facets)


def article_primary_facets(article: Article) -> set[str]:
    return set(
        cached_article_primary_facets(
            article.title,
            article.summary,
            tuple(article.key_facts[:8]),
        )
    )


def event_primary_facets(event: Event) -> set[str]:
    facets: set[str] = set()
    for article in event.articles:
        facets |= article_primary_facets(article)
    return facets


def article_splittable_topic_facets(article: Article) -> set[str]:
    facets = effective_topic_facets(article_primary_facets(article))
    splittable = facets & SPLITTABLE_TOPIC_FACETS
    splittable |= {facet for facet in facets if facet.startswith("malware-family-")}
    specific = splittable - BRIDGE_SPLIT_TOPIC_FACETS
    return specific or splittable


