def is_direct_apple_first_party_program_story(title: str, text: str) -> bool:
    """Recognize an Apple-owned plan or program even when a partner funds it."""
    identity = title_led_identity(title, text)
    if identity.scope != "apple-direct" or identity.content_form != "news":
        return False
    if "office-real-estate" in identity.components:
        return False
    if (
        "financed-device-restriction" in identity.title_components
        and "apple-device-leasing-program" not in identity.title_components
    ):
        return False
    lead = title_and_lead_scope(title, text, limit=900).lower()
    program_language = score_terms(
        lead,
        [
            "program",
            "programme",
            "plan",
            "leasing",
            "lease",
            "subscription",
            "monthly device",
            "月租",
            "租赁计划",
            "换新计划",
            "升级计划",
        ],
    ) > 0
    # A first-party program must be the title subject. Apple-owned names found
    # only in the lead can be comparison/background for a third-party plan.
    apple_owned_subject = any(
        subject.startswith("apple-") for subject in identity.title_named_subjects
    )
    apple_action = bool(
        identity.actions
        & {
            "delay-roadmap",
            "feature-change",
            "project-cancellation",
            "retail-availability",
            "transaction",
        }
    )
    device_program_anchor = bool(
        "apple-device-leasing-program" in identity.title_components
        or score_terms(
            title.lower(),
            [
                "device leasing",
                "lease new devices",
                "hardware subscription",
                "iphone upgrade program",
                "apple upgrade",
                "设备租赁",
                "硬件租赁",
                "设备月租",
            ],
        )
        > 0
    )
    return device_program_anchor and program_language and apple_action and (
        apple_owned_subject
        or bool(re.match(r"^(?:apple(?:'s)?|苹果|消息称苹果|报道称苹果)", title.lower()))
    )


def is_apple_operated_activity_challenge_story(title: str, text: str) -> bool:
    """Recognize Apple-run fitness challenges without promoting third-party app news."""
    title_lower = clean_sentence(title).lower()
    scope = title_and_lead_scope(title, text, limit=900).lower()
    apple_title_actor = bool(
        re.match(r"^(?:apple(?:'s)?|苹果(?:公司)?)\b", title_lower)
        or re.match(r"^苹果", title_lower)
    )
    branded_challenge = bool(
        re.search(
            r"\bapple\s+watch\s+(?:activity|fitness|workout)\s+challenge\b",
            title_lower,
        )
    )
    if not (apple_title_actor or branded_challenge):
        return False
    challenge = score_terms(
        scope,
        [
            "activity challenge",
            "fitness challenge",
            "workout challenge",
            "challenge",
            "活动挑战",
            "健身挑战",
            "运动挑战",
            "用户挑战",
            "挑战",
        ],
    ) > 0
    first_party_surface = score_terms(
        scope,
        [
            "apple watch",
            "fitness app",
            "activity app",
            "workout app",
            "health app",
            "健身 app",
            "体能训练",
            "健康 app",
        ],
    ) > 0
    reward_or_invitation = score_terms(
        scope,
        [
            "badge",
            "award",
            "medal",
            "invites users",
            "inviting users",
            "limited-edition",
            "限量奖章",
            "限定奖章",
            "勋章",
            "邀请用户",
            "邀请 apple watch 用户",
        ],
    ) > 0
    direct_launch = score_terms(
        scope,
        [
            "apple will launch",
            "apple launches",
            "apple announced",
            "苹果将推出",
            "苹果推出",
            "苹果宣布",
        ],
    ) > 0
    return challenge and first_party_surface and (
        reward_or_invitation or (branded_challenge and direct_launch)
    )


def is_direct_apple_restricted_mode_clarification_story(title: str, text: str) -> bool:
    """Keep Apple's affirmative clarification even when it negates a rumored use."""
    scope = title_and_lead_scope(title, text, limit=1200).lower()
    if effective_apple_term_score(scope) <= 0:
        return False
    restriction = score_terms(
        scope,
        [
            "restricted mode",
            "finance lock",
            "cut off apps",
            "受限模式",
            "金融锁",
            "限制应用",
        ],
    ) > 0
    financing = score_terms(
        scope,
        [
            "lease",
            "leases",
            "leasing",
            "financed",
            "financing",
            "missed payment",
            "apple upgrade",
            "租赁",
            "月租",
            "分期",
            "欠款",
        ],
    ) > 0
    clarification = score_terms(
        scope,
        [
            "apple says",
            "apple said",
            "apple clarified",
            "isn't for",
            "is not for",
            "won't turn on",
            "will not turn on",
            "not used for",
            "苹果表示",
            "苹果澄清",
            "不会启用",
            "不用于",
            "并非用于",
        ],
    ) > 0
    return restriction and financing and clarification


def is_direct_apple_supplier_cost_change_story(title: str, text: str) -> bool:
    """Keep supplier price changes that explicitly alter Apple product input costs."""
    title_lower = title.lower()
    lead = title_and_lead_scope(title, text, limit=1000).lower()
    price_change = score_terms(
        title_lower,
        [
            "price hike",
            "price hikes",
            "raises prices",
            "increases prices",
            "increases chip costs",
            "cost more",
            "costs more",
            "涨价",
            "提价",
            "上调价格",
            "提高价格",
            "芯片成本",
        ],
    ) > 0
    if not price_change:
        return False
    supplier_title = score_terms(
        title_lower,
        [
            "supplier",
            "chipmaker",
            "foundry",
            "tsmc",
            "samsung display",
            "micron",
            "sk hynix",
            "供应商",
            "代工厂",
            "台积电",
            "三星显示",
            "美光",
            "海力士",
        ],
    ) > 0
    apple_cost_link = score_terms(
        lead,
        [
            "apple chip",
            "apple chips",
            "apple processor",
            "apple processors",
            "apple's costs",
            "apple costs",
            "iphone costs",
            "ipad costs",
            "mac costs",
            "苹果芯片",
            "苹果处理器",
            "苹果成本",
            "iphone 成本",
            "ipad 成本",
            "mac 成本",
        ],
    ) > 0
    return supplier_title and (
        apple_cost_link
        or bool(hardware_product_families_from_text(title))
        or effective_apple_term_score(title) > 0
    )


