def event_category_from_metadata(title: str, summary: str, key_facts: list[str], event_kind: str) -> str:
    context = " ".join([summary, *key_facts[:5]])
    if is_apple_hardware_leadership_personnel_story(title, context):
        return "hardware_products"
    if is_india_tariff_iphone_manufacturing_story(f"{title} {context}"):
        return "hardware_products"
    if is_hardware_focused_apple_legal_story(title, context):
        return "hardware_products"
    if is_material_apple_stock_move_story(title, context):
        return "hardware_products"
    if event_kind in SOFTWARE_EVENT_KINDS:
        return "software_systems"
    if event_kind in HARDWARE_EVENT_KINDS:
        return "hardware_products"
    return choose_category(title, context)


def articles_form_cohesive_os_release_wave(articles: list[Article]) -> bool:
    if len(articles) < 2:
        return False
    wave_sets = [article_os_wave_components(article) for article in articles]
    if any(not waves for waves in wave_sets):
        return False
    stage_sets = [
        {wave.rsplit(":", 1)[-1] for wave in waves}
        for waves in wave_sets
    ]
    if not set.intersection(*stage_sets):
        return False
    versioned_waves = {
        wave
        for waves in wave_sets
        for wave in waves
        if wave.startswith("os-wave:")
    }
    if len(versioned_waves) > 1:
        return False
    if versioned_waves and all(not wave.endswith(":final") for wave in versioned_waves):
        return True
    platform_sets = [
        merge_guard_platform_facets(article_primary_facets(article))
        for article in articles
    ]
    if any(not platforms for platforms in platform_sets):
        return False
    return all(
        platform_facets_compatible(left, right)
        for index, left in enumerate(platform_sets)
        for right in platform_sets[index + 1 :]
    )


def articles_form_cohesive_named_os_component_action(articles: list[Article]) -> bool:
    """Recognize a concrete OS component action despite release-vs-feature headlines."""
    if len(articles) < 2:
        return False
    identities = [article_title_led_event_identity(article) for article in articles]
    component_sets = [
        {
            component
            for component in identity.components
            if component.startswith("os-component:") or component == "spotlight-index-preparation"
        }
        for identity in identities
    ]
    if any(not components for components in component_sets):
        return False
    common_components = set.intersection(*component_sets)
    if not common_components:
        return False
    version_sets = [apple_os_version_values_from_text(article.title) for article in articles]
    if not (version_sets and all(version_sets) and set.intersection(*version_sets)):
        return False
    if "spotlight-index-preparation" in common_components:
        return True
    shared_title_tokens = set.intersection(
        *(article_tokens(article.title, "") for article in articles)
    )
    generic_component_tokens = {
        "apple",
        "app",
        "application",
        "beta",
        "feature",
        "ios",
        "ipados",
        "macos",
        "watchos",
        "tvos",
        "visionos",
        "mail",
        "messages",
        "notes",
        "weather",
        "shortcuts",
        "邮件",
        "信息",
        "备忘录",
        "天气",
        "快捷指令",
    }
    specific_shared = {
        token
        for token in strong_shared_merge_tokens(shared_title_tokens)
        if token not in generic_component_tokens and not re.fullmatch(r"\d+(?:\.\d+)?", token)
    }
    return bool(specific_shared)


def event_merge_warnings(articles: list[Article]) -> list[str]:
    warnings: list[str] = []
    kinds = {item.event_kind for item in articles if item.event_kind != "general_company"}
    regions = set().union(*(item.regions for item in articles)) if articles else set()
    normalized_regions = regions - {"multi-region"}
    facet_sets = [effective_topic_facets(article_primary_facets(item)) for item in articles]
    explicit_facet_sets = [facets for facets in facet_sets if facets]
    common_facets = set.intersection(*explicit_facet_sets) if len(explicit_facet_sets) > 1 else set()
    title_identity_cohesive = articles_share_cohesive_title_identity(articles)
    cohesive_os_wave = articles_form_cohesive_os_release_wave(articles)
    cohesive_named_os_component = articles_form_cohesive_named_os_component_action(articles)
    cohesive_market_report = articles_form_cohesive_market_report(articles)
    same_global_market_report = articles_form_same_global_market_report(articles)
    cohesive_first_party_program = len(articles) > 1 and all(
        is_direct_apple_first_party_program_story(item.title, item.summary)
        for item in articles
    )
    valuation_signatures = [
        apple_stock_move_metric_signatures(article_merge_context(item))
        & {signature for signature in apple_stock_move_metric_signatures(article_merge_context(item)) if signature.startswith("valuation:")}
        for item in articles
    ]
    cohesive_company_valuation = bool(
        len(valuation_signatures) > 1
        and all(valuation_signatures)
        and all(
            is_material_apple_stock_move_story(item.title, article_merge_context(item))
            or "ranking:apple-over-nvidia"
            in apple_stock_move_metric_signatures(article_merge_context(item))
            for item in articles
        )
    )
    cohesive_legacy_macos_update = len(articles) > 1 and all(
        same_legacy_macos_pair_update_event(left, singleton_merge_event(right))
        for index, left in enumerate(articles)
        for right in articles[index + 1 :]
    )
    cohesive_named_service_content = len(articles) > 1 and all(
        same_named_service_content_action_event(left, singleton_merge_event(right))
        for index, left in enumerate(articles)
        for right in articles[index + 1 :]
    )
    cohesive_restricted_memory_supplier_action = len(articles) > 1 and all(
        is_apple_memory_supplier_sourcing_story(article_merge_context(item))
        or is_apple_restricted_memory_supplier_approval_story(article_merge_context(item))
        for item in articles
    )
    if (
        len(kinds) > 1
        and not common_facets
        and not title_identity_cohesive
        and not cohesive_os_wave
        and not cohesive_named_os_component
        and not cohesive_market_report
        and not cohesive_legacy_macos_update
        and not cohesive_named_service_content
        and not cohesive_first_party_program
        and not cohesive_company_valuation
    ):
        warnings.append("mixed event kinds")
    if (
        len(articles) > 1
        and
        len(normalized_regions) > 1
        and not any(item.event_kind not in REGION_SENSITIVE_EVENT_KINDS for item in articles)
        and not (common_facets & REGION_WARNING_EXEMPT_FACETS)
        and not title_identity_cohesive
        and not cohesive_market_report
        and not same_global_market_report
        and not cohesive_company_valuation
        and not cohesive_restricted_memory_supplier_action
    ):
        warnings.append("multiple region-specific markers")
    tiers = {item.relevance_tier for item in articles}
    if "weak" in tiers and len(tiers) > 1:
        warnings.append("mixed relevance tiers")
    if len(explicit_facet_sets) > 1:
        all_foldable_panel_market_reports = all(
            is_foldable_iphone_panel_market_report_context(" ".join([item.title, item.summary, *item.key_facts[:4]]))
            for item in articles
        )
        if (
            not common_facets
            and not all_foldable_panel_market_reports
            and not title_identity_cohesive
            and not cohesive_os_wave
            and not cohesive_named_os_component
            and not cohesive_market_report
            and not cohesive_legacy_macos_update
            and not cohesive_named_service_content
            and not cohesive_first_party_program
            and not cohesive_company_valuation
        ):
            warnings.append("mixed primary topic facets")
    return warnings


