def iphone_product_identity_anchors(text: str) -> set[str]:
    lower = text.lower()
    anchors = {
        f"iphone-{match.group(1)}"
        for match in re.finditer(r"(?<![a-z0-9])iphone\s*(\d{1,2})(?!\d)", lower)
    }
    if score_terms(
        lower,
        [
            "foldable iphone",
            "folding iphone",
            "iphone fold",
            "iphone ultra",
            "折叠屏 iphone",
            "折叠 iphone",
            "折叠屏iphone",
            "折叠iphone",
            "首款折叠屏",
            "首款折叠手机",
        ],
    ) > 0:
        anchors.add("foldable-iphone")
    return anchors


